    ]
  },
  {
    "alert_id": "EX2_TDF_MONITORING_002",
    "title": "TDF renal monitoring gap: no eGFR documented",
    "message": "Guidelines require serum creatinine and eGFR monitoring every 12 months for patients on TDF. The patient has been on TLD for 2 years, but only one creatinine result (0.9 mg/dL from 2025-02-14) is documented, and no eGFR values are recorded. While the current acute creatinine of 2.4 is being addressed, a baseline and routine eGFR should be documented to distinguish acute injury from chronic decline and to guide future TDF eligibility.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Calculate and document eGFR with current creatinine. After rehydration, repeat creatinine and eGFR to establish a new baseline before deciding on TDF resumption.",
    "citations": [
      {"page_number": 27, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p27_c2"}
    ]
  }
]
